mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("[1,3,-1,-3,5,3,6,7]","1,-1,-1,3,5,6"),
        ("[2,1,4]","2"),
        ("[1,2,3,4,5,6,7]","2,3,4,5,6"),
        ("[3,3,3,3,3,3,3]","3,3,3,3,3"),
        ("[8,7,6,5,4,3,2]","7,6,5,4,3"),
        ("  \n[1,3,-1,-3,5,3,6,7]\n  ","1,-1,-1,3,5,6"),
        ("\n[8,7,6,5,4,3,2]\n","7,6,5,4,3")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS dual-heap-window-median");
}
